// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 seedValue) public {
        vm.assume(user != address(0));
        // Seed the market so buyDrugs works
        c.seedMarket(1e6);
        // Get free kilos for the user so they have some drugs to sell later if needed
        vm.prank(user);
        c.getFreeKilo();
        // Prepare ETH for the user
        uint256 ethAmount = bound(seedValue, 0.001 ether, 100 ether);
        vm.deal(user, ethAmount);
        // Calculate expected increase before call
        uint256 balanceBefore = address(c).balance;
        uint256 drugsBoughtExpected = c.calculateDrugBuy(ethAmount, balanceBefore);
        uint256 expectedIncrease = drugsBoughtExpected - c.devFee(drugsBoughtExpected);
        // Record claimed before
        uint256 claimedBefore = c.claimedDrugs(user);
        // Call buyDrugs
        vm.prank(user);
        c.buyDrugs{value: ethAmount}();
        // Assert: increase equals expected
        uint256 claimedAfter = c.claimedDrugs(user);
        assertTrue(claimedAfter - claimedBefore == expectedIncrease, "claimedDrugs increase should be drugsBought minus dev fee");
    }
}

